The bug is caused by SQL’s three-valued `NULL` logic:

- `col IN (1, NULL)` does **not** match rows where `col IS NULL`.
- `col NOT IN (1, NULL)` is even worse: because `col != NULL` is `UNKNOWN`, it can filter out rows that should otherwise match.
- When fixing this, the generated replacement contains `OR`/`AND`, so it must be parenthesized when embedded inside larger `AND`/`OR` groups.

Below is the complete fixed code. The included test functions fail against the original implementation and pass with this fix.

```python
"""SQL query builder with support for complex WHERE clauses."""
from typing import Any, List, Optional, Union, Tuple
from enum import Enum
from dataclasses import dataclass


class Op(Enum):
    EQ = "="
    NE = "!="
    LT = "<"
    GT = ">"
    LTE = "<="
    GTE = ">="
    LIKE = "LIKE"
    IN = "IN"
    NOT_IN = "NOT IN"
    IS_NULL = "IS NULL"
    IS_NOT_NULL = "IS NOT NULL"
    BETWEEN = "BETWEEN"


@dataclass
class Condition:
    column: str
    op: Op
    value: Any = None


@dataclass
class ConditionGroup:
    conditions: List[Union["Condition", "ConditionGroup"]]
    logic: str = "AND"  # AND or OR


@dataclass
class OrderBy:
    column: str
    direction: str = "ASC"


@dataclass
class JoinClause:
    table: str
    on: str
    join_type: str = "INNER"


class QueryBuilder:
    def __init__(self, table: str):
        self.table = table
        self._select: List[str] = ["*"]
        self._where: Optional[ConditionGroup] = None
        self._order_by: List[OrderBy] = []
        self._limit: Optional[int] = None
        self._offset: Optional[int] = None
        self._joins: List[JoinClause] = []
        self._group_by: List[str] = []
        self._having: Optional[ConditionGroup] = None
        self._params: List[Any] = []

    def select(self, *columns: str) -> "QueryBuilder":
        self._select = list(columns)
        return self

    def where(self, *conditions: Union[Condition, ConditionGroup]) -> "QueryBuilder":
        if len(conditions) == 1 and isinstance(conditions[0], ConditionGroup):
            self._where = conditions[0]
        else:
            self._where = ConditionGroup(conditions=list(conditions), logic="AND")
        return self

    def order_by(self, column: str, direction: str = "ASC") -> "QueryBuilder":
        self._order_by.append(OrderBy(column=column, direction=direction))
        return self

    def limit(self, n: int) -> "QueryBuilder":
        self._limit = n
        return self

    def offset(self, n: int) -> "QueryBuilder":
        self._offset = n
        return self

    def join(self, table: str, on: str, join_type: str = "INNER") -> "QueryBuilder":
        self._joins.append(JoinClause(table=table, on=on, join_type=join_type))
        return self

    def group_by(self, *columns: str) -> "QueryBuilder":
        self._group_by = list(columns)
        return self

    def having(self, *conditions: Union[Condition, ConditionGroup]) -> "QueryBuilder":
        if len(conditions) == 1 and isinstance(conditions[0], ConditionGroup):
            self._having = conditions[0]
        else:
            self._having = ConditionGroup(conditions=list(conditions), logic="AND")
        return self

    def build(self) -> Tuple[str, List[Any]]:
        self._params = []

        parts = [f"SELECT {', '.join(self._select)}"]
        parts.append(f"FROM {self.table}")

        for j in self._joins:
            parts.append(f"{j.join_type} JOIN {j.table} ON {j.on}")

        if self._where:
            where_sql = self._build_condition_group(self._where)
            parts.append(f"WHERE {where_sql}")

        if self._group_by:
            parts.append(f"GROUP BY {', '.join(self._group_by)}")

        if self._having:
            having_sql = self._build_condition_group(self._having)
            parts.append(f"HAVING {having_sql}")

        if self._order_by:
            order_parts = [f"{o.column} {o.direction}" for o in self._order_by]
            parts.append(f"ORDER BY {', '.join(order_parts)}")

        if self._limit is not None:
            parts.append(f"LIMIT {self._limit}")

        if self._offset is not None:
            parts.append(f"OFFSET {self._offset}")

        return " ".join(parts), self._params

    def _build_condition_group(self, group: ConditionGroup) -> str:
        parts = []

        for cond in group.conditions:
            if isinstance(cond, ConditionGroup):
                sub = self._build_condition_group(cond)
                parts.append(f"({sub})")
            elif isinstance(cond, Condition):
                parts.append(self._build_condition(cond))

        return f" {group.logic} ".join(parts)

    def _build_condition(self, cond: Condition) -> str:
        if cond.op == Op.IS_NULL:
            return f"{cond.column} IS NULL"

        if cond.op == Op.IS_NOT_NULL:
            return f"{cond.column} IS NOT NULL"

        if cond.op == Op.BETWEEN:
            self._params.extend(cond.value)
            return f"{cond.column} BETWEEN ? AND ?"

        if cond.op in (Op.IN, Op.NOT_IN):
            return self._build_in_condition(cond)

        self._params.append(cond.value)
        return f"{cond.column} {cond.op.value} ?"

    def _build_in_condition(self, cond: Condition) -> str:
        """
        Build IN / NOT IN conditions with correct NULL semantics.

        SQL does not treat NULL as a comparable value inside IN lists:

            col IN (1, NULL)

        does not match rows where col IS NULL.

        Also:

            col NOT IN (1, NULL)

        usually matches no non-NULL values because the NULL comparison produces UNKNOWN.

        Therefore:
            IN     with NULL becomes:     (col IN (...) OR col IS NULL)
            NOT IN with NULL becomes:     (col NOT IN (...) AND col IS NOT NULL)

        The returned expression is parenthesized whenever it becomes compound so that
        nesting inside AND/OR groups remains correct.
        """
        raw_values = cond.value if isinstance(cond.value, (list, tuple)) else [cond.value]
        values = list(raw_values)

        non_null_values = [v for v in values if v is not None]
        has_null = len(non_null_values) != len(values)

        def value_list_sql(op: str) -> Optional[str]:
            if not non_null_values:
                return None

            placeholders = ", ".join("?" for _ in non_null_values)
            self._params.extend(non_null_values)
            return f"{cond.column} {op} ({placeholders})"

        if cond.op == Op.IN:
            in_sql = value_list_sql("IN")

            if has_null:
                if in_sql is None:
                    return f"({cond.column} IS NULL)"
                return f"({in_sql} OR {cond.column} IS NULL)"

            # Empty IN list should be a condition that can never be true.
            if in_sql is None:
                return "(1 = 0)"

            return in_sql

        # cond.op == Op.NOT_IN
        not_in_sql = value_list_sql("NOT IN")

        if has_null:
            if not_in_sql is None:
                return f"({cond.column} IS NOT NULL)"
            return f"({not_in_sql} AND {cond.column} IS NOT NULL)"

        # Empty NOT IN list should be a condition that is always true.
        if not_in_sql is None:
            return "(1 = 1)"

        return not_in_sql


# Helper functions
def and_(*conditions) -> ConditionGroup:
    return ConditionGroup(conditions=list(conditions), logic="AND")


def or_(*conditions) -> ConditionGroup:
    return ConditionGroup(conditions=list(conditions), logic="OR")


def eq(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.EQ, value=val)


def ne(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.NE, value=val)


def lt(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.LT, value=val)


def gt(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.GT, value=val)


def in_(col: str, vals: List[Any]) -> Condition:
    return Condition(column=col, op=Op.IN, value=vals)


def not_in(col: str, vals: List[Any]) -> Condition:
    return Condition(column=col, op=Op.NOT_IN, value=vals)


def is_null(col: str) -> Condition:
    return Condition(column=col, op=Op.IS_NULL)


def between(col: str, low: Any, high: Any) -> Condition:
    return Condition(column=col, op=Op.BETWEEN, value=[low, high])


# Tests
def test_nested_or_in_with_null_bug() -> None:
    """
    This test fails against the original implementation.

    Original SQL would be roughly:

        role IN (?, ?)

    with params:

        ["admin", None]

    That does not match rows where role IS NULL.
    """
    import sqlite3

    qb = (
        QueryBuilder("users")
        .select("id")
        .where(
            and_(
                eq("tenant_id", 1),
                or_(
                    eq("status", "active"),
                    in_("role", ["admin", None]),
                ),
            )
        )
        .order_by("id")
    )

    sql, params = qb.build()

    assert sql == (
        "SELECT id FROM users "
        "WHERE tenant_id = ? AND (status = ? OR (role IN (?) OR role IS NULL)) "
        "ORDER BY id ASC"
    )
    assert params == [1, "active", "admin"]

    conn = sqlite3.connect(":memory:")

    try:
        conn.execute(
            """
            CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                tenant_id INTEGER NOT NULL,
                status TEXT NOT NULL,
                role TEXT NULL
            )
            """
        )

        conn.executemany(
            "INSERT INTO users (id, tenant_id, status, role) VALUES (?, ?, ?, ?)",
            [
                (1, 1, "active", "user"),      # matches status
                (2, 1, "inactive", "admin"),  # matches role IN ('admin')
                (3, 1, "inactive", None),     # should match role IS NULL
                (4, 1, "inactive", "guest"),  # does not match
                (5, 2, "active", None),       # wrong tenant
            ],
        )

        rows = [row[0] for row in conn.execute(sql, params).fetchall()]

        assert rows == [1, 2, 3]
    finally:
        conn.close()


def test_nested_or_not_in_with_null_bug() -> None:
    """
    This test also fails against the original implementation.

    Original SQL would be roughly:

        role NOT IN (?, ?)

    with params:

        ["admin", None]

    Because the list contains NULL, SQL's NOT IN behavior filters out rows like
    role = 'guest', even though they should match the intended condition.
    """
    import sqlite3

    qb = (
        QueryBuilder("users")
        .select("id")
        .where(
            or_(
                eq("status", "vip"),
                not_in("role", ["admin", None]),
            )
        )
        .order_by("id")
    )

    sql, params = qb.build()

    assert sql == (
        "SELECT id FROM users "
        "WHERE status = ? OR (role NOT IN (?) AND role IS NOT NULL) "
        "ORDER BY id ASC"
    )
    assert params == ["vip", "admin"]

    conn = sqlite3.connect(":memory:")

    try:
        conn.execute(
            """
            CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                status TEXT NOT NULL,
                role TEXT NULL
            )
            """
        )

        conn.executemany(
            "INSERT INTO users (id, status, role) VALUES (?, ?, ?)",
            [
                (1, "normal", "guest"),   # should match NOT IN ('admin') AND IS NOT NULL
                (2, "normal", "admin"),   # should not match
                (3, "normal", None),      # should not match because None was in excluded list
                (4, "vip", None),         # matches status
            ],
        )

        rows = [row[0] for row in conn.execute(sql, params).fetchall()]

        assert rows == [1, 4]
    finally:
        conn.close()


if __name__ == "__main__":
    test_nested_or_in_with_null_bug()
    test_nested_or_not_in_with_null_bug()
    print("All tests passed.")
